from jsonb_to_recordset($q$[{"id":3339,"materia":"adua","nivel":0,"enunciado":"Siscomex é a sigla de:","opcoes":["Sistema Integrado de Comércio Exterior","Sistema de Controle de Mercadorias","Serviço Integrado de Câmbio Externo do Banco Central","Sistema Comercial do Mercosul"],"explicacao":"Sistema informatizado que registra as operações de comércio exterior."},{"id":3340,"materia":"adua","nivel":0,"enunciado":"A loja que vende mercadorias a viajantes internacionais em aeroportos, com regime aduaneiro especial, é a:","opcoes":["Loja franca (free shop)","Loja de departamento","Loja de conveniência de rodovia federal","Loja de consignação"],"explicacao":"Regime especial de loja franca."},{"id":3341,"materia":"adua","nivel":0,"enunciado":"A Zona Franca de Manaus fica no estado do:","opcoes":["Amazonas","Pará","Acre","Roraima e Amapá"],"explicacao":"Criada para estimular o desenvolvimento da Amazônia Ocidental."},{"id":3342,"materia":"adua","nivel":1,"enunciado":"Pelo Regulamento Aduaneiro, o território aduaneiro compreende:","opcoes":["Todo o território nacional","Apenas os portos e aeroportos","Somente as faixas de fronteira","Apenas a zona primária"],"explicacao":"Divide-se em zona primária e zona secundária."},{"id":3343,"materia":"adua","nivel":1,"enunciado":"Na jurisdição aduaneira, a zona primária abrange:","opcoes":["Portos, aeroportos e pontos de fronteira alfandegados","Todo o território fora dos portos","Apenas as capitais dos estados","As zonas francas, as áreas de livre comércio e as capitais"],"explicacao":"O restante do território é zona secundária."},{"id":3344,"materia":"adua","nivel":1,"enunciado":"O fato gerador do Imposto de Importação é:","opcoes":["A entrada de mercadoria estrangeira no território aduaneiro","A compra da mercadoria no exterior, com a assinatura do contrato de câmbio","O pagamento do frete internacional","A revenda da mercadoria no Brasil"],"explicacao":"Art. 19 do CTN e art. 72 do Regulamento Aduaneiro."},{"id":3345,"materia":"adua","nivel":1,"enunciado":"Em regra, o contribuinte do Imposto de Importação é:","opcoes":["O importador","O transportador","O vendedor estrangeiro","O despachante aduaneiro"],"explicacao":"Também o destinatário de remessa postal e o adquirente em licitação."},{"id":3346,"materia":"adua","nivel":2,"enunciado":"Para cálculo do Imposto de Importação, considera-se ocorrido o fato gerador, em regra, na data:","opcoes":["Do registro da declaração de importação para consumo","Do embarque no país de origem","Da emissão da fatura comercial pelo vendedor estrangeiro","Da chegada do navio ao porto"],"explicacao":"Art. 73, I do Regulamento Aduaneiro."},{"id":3347,"materia":"adua","nivel":2,"enunciado":"Na alíquota ad valorem, a base de cálculo do Imposto de Importação é:","opcoes":["O valor aduaneiro, apurado conforme o Acordo de Valoração Aduaneira","O preço de venda no varejo brasileiro, apurado em pesquisa da Receita","O valor declarado pelo transportador","O custo de produção no Brasil"],"explicacao":"Acordo sobre a implementação do Artigo VII do GATT."},{"id":3348,"materia":"adua","nivel":2,"enunciado":"Pelo Acordo de Valoração Aduaneira, o primeiro método a ser aplicado é o:","opcoes":["Valor de transação","Valor computado","Valor dedutivo","Método da razoabilidade"],"explicacao":"Os demais métodos só se aplicam sucessivamente."},{"id":3349,"materia":"adua","nivel":2,"enunciado":"O fato gerador do Imposto de Exportação é:","opcoes":["A saída da mercadoria nacional ou nacionalizada do território nacional","A produção da mercadoria no Brasil","O pagamento ao exportador","A chegada da mercadoria ao destino final, comprovada pelo importador estrangeiro"],"explicacao":"Considera-se ocorrido na data do registro da exportação no Siscomex."},{"id":3350,"materia":"adua","nivel":2,"enunciado":"No despacho de importação, o canal verde de parametrização indica:","opcoes":["Desembaraço automático, sem exame documental nem verificação física","Exame documental obrigatório","Exame documental e verificação física da mercadoria pela fiscalização","Procedimento especial por suspeita de fraude"],"explicacao":"Amarelo: documental; vermelho: documental e física; cinza: procedimento especial."},{"id":3351,"materia":"adua","nivel":2,"enunciado":"O regime de trânsito aduaneiro permite:","opcoes":["Transportar mercadoria sob controle aduaneiro entre pontos do território, com suspensão de tributos","Vender mercadoria importada a qualquer comprador no país sem pagar tributos, desde que haja nota fiscal","Exportar sem registro no Siscomex","Guardar mercadoria por prazo indeterminado"],"explicacao":"Arts. 315 e seguintes do Regulamento Aduaneiro."},{"id":3352,"materia":"adua","nivel":2,"enunciado":"No drawback, os insumos importados com benefício fiscal destinam-se a:","opcoes":["Produzir bens que serão exportados","Abastecer o mercado interno","Uso pessoal do importador","Doação a entidades públicas e filantrópicas"],"explicacao":"Modalidades: suspensão, isenção e restituição."},{"id":3353,"materia":"adua","nivel":3,"enunciado":"Na admissão temporária para utilização econômica, os tributos são pagos:","opcoes":["Proporcionalmente ao tempo de permanência do bem no país","Integralmente na entrada","Somente na saída do bem","Nunca, pois há isenção total para bens de uso temporário"],"explicacao":"1% ao mês sobre o montante devido no regime comum."},{"id":3354,"materia":"adua","nivel":3,"enunciado":"No regime de exportação temporária para aperfeiçoamento passivo, no retorno do bem tributa-se:","opcoes":["Em regra, apenas o valor agregado no exterior","O valor integral do bem","Nada, pois há isenção total no retorno do bem","Somente o frete de retorno"],"explicacao":"Usado para conserto, reparo ou transformação no exterior."},{"id":3355,"materia":"adua","nivel":3,"enunciado":"O entreposto aduaneiro na importação permite:","opcoes":["Armazenar mercadoria em recinto alfandegado com suspensão do pagamento de tributos","Vender ao consumidor final sem tributos, em lojas instaladas no porto ou aeroporto","Industrializar sem qualquer controle","Retirar mercadoria sem despacho"],"explicacao":"Arts. 404 e seguintes do Regulamento Aduaneiro."},{"id":3356,"materia":"adua","nivel":3,"enunciado":"O canal cinza de parametrização envolve:","opcoes":["Exame documental, verificação física e procedimento especial de controle, como suspeita de fraude","Liberação imediata da carga","Apenas exame documental","Somente a cobrança da taxa do Siscomex, sem análise documental nem verificação física da carga"],"explicacao":"Pode envolver análise do valor aduaneiro."},{"id":3357,"materia":"adua","nivel":3,"enunciado":"A revisão aduaneira é o ato pelo qual se apura, após o desembaraço:","opcoes":["A regularidade do pagamento dos tributos e da aplicação de benefícios fiscais","A qualidade técnica da mercadoria","A origem do capital do importador e de seus sócios estrangeiros no exterior","O valor do frete marítimo"],"explicacao":"Deve ser concluída no prazo de 5 anos."},{"id":3358,"materia":"adua","nivel":3,"enunciado":"Os direitos antidumping são aplicados quando o produto é exportado ao Brasil:","opcoes":["A preço inferior ao seu valor normal no mercado do exportador","Com qualidade inferior à do produto brasileiro similar","Sem certificado de origem","Por empresa sem filial no Brasil"],"explicacao":"Não têm natureza de tributo."},{"id":3359,"materia":"adua","nivel":3,"enunciado":"O Recof permite à empresa:","opcoes":["Importar ou adquirir insumos com suspensão de tributos para industrializar, sob controle informatizado","Exportar sem emitir nota fiscal","Pagar tributos só ao final de cada ano","Vender no mercado interno sem tributação, desde que a empresa seja certificada pelo Ministério da Economia"],"explicacao":"Regime de entreposto industrial sob controle aduaneiro informatizado."},{"id":3360,"materia":"adua","nivel":4,"enunciado":"A Zona Franca de Manaus teve seus benefícios prorrogados pela EC 83/2014 até:","opcoes":["2073","2033","2050","2100"],"explicacao":"Acrescentou 50 anos ao prazo do art. 40 do ADCT."},{"id":3361,"materia":"adua","nivel":4,"enunciado":"A mercadoria descarregada em recinto alfandegado de zona primária é considerada abandonada se não for iniciado o despacho em:","opcoes":["90 dias","30 dias","180 dias","1 ano"],"explicacao":"Decreto-Lei 1.455/1976, art. 23, II, a. Há outros prazos para entreposto e zona secundária."},{"id":3362,"materia":"adua","nivel":4,"enunciado":"A pena de perdimento da mercadoria, quando ela não é localizada ou foi consumida, é convertida em:","opcoes":["Multa equivalente ao valor aduaneiro da mercadoria","Advertência ao importador","Prisão administrativa","Suspensão do CNPJ do importador por 30 dias"],"explicacao":"Decreto-Lei 1.455/1976, art. 23, § 3º."},{"id":3363,"materia":"adua","nivel":4,"enunciado":"O Repetro é o regime aduaneiro especial voltado a bens destinados:","opcoes":["À pesquisa e à lavra de jazidas de petróleo e gás natural","À modernização e à ampliação da estrutura dos portos","À produção de veículos","À importação de livros"],"explicacao":"O Reporto é o regime dos portos."},{"id":3364,"materia":"trib","nivel":0,"enunciado":"A sigla IPI significa:","opcoes":["Imposto sobre Produtos Industrializados","Imposto Predial Integrado","Índice de Preços Industriais","Imposto sobre Patrimônio Imobiliário Urbano"],"explicacao":"Imposto federal de caráter seletivo."},{"id":3365,"materia":"trib","nivel":0,"enunciado":"O ITR é o imposto federal sobre:","opcoes":["A propriedade territorial rural","A transmissão de imóveis","A renda de trabalhadores rurais","A venda de produtos agrícolas"],"explicacao":"Art. 153, VI da CF."},{"id":3366,"materia":"trib","nivel":1,"enunciado":"Pelo CTN, o fato gerador do Imposto de Renda é a aquisição da disponibilidade:","opcoes":["Econômica ou jurídica de renda e proventos de qualquer natureza","Apenas financeira de salários","Apenas de bens imóveis","Somente de lucros distribuídos aos sócios de empresas"],"explicacao":"Art. 43 do CTN."},{"id":3367,"materia":"trib","nivel":1,"enunciado":"O carnê-leão é o recolhimento mensal obrigatório da pessoa física sobre rendimentos recebidos:","opcoes":["De outras pessoas físicas ou do exterior, sem retenção na fonte","Exclusivamente de salário com carteira assinada e retenção pelo empregador","De aplicações em poupança","De prêmios de loteria"],"explicacao":"Ex.: aluguéis recebidos de pessoa física."},{"id":3368,"materia":"trib","nivel":2,"enunciado":"No regime não cumulativo, as alíquotas básicas de PIS e Cofins são, respectivamente:","opcoes":["1,65% e 7,6%","0,65% e 3%","3% e 0,65%","7,6% e 1,65%"],"explicacao":"No cumulativo, 0,65% e 3%."},{"id":3369,"materia":"trib","nivel":2,"enunciado":"A alíquota geral da CSLL para as pessoas jurídicas em geral é de:","opcoes":["9%","15%","25%","34%"],"explicacao":"Instituições financeiras têm alíquotas maiores."},{"id":3370,"materia":"trib","nivel":2,"enunciado":"O adicional do IRPJ, de 10%, incide sobre a parcela do lucro que exceder, por mês:","opcoes":["R$ 20.000,00","R$ 10.000,00","R$ 50.000,00","R$ 100.000,00"],"explicacao":"Equivale a R$ 240 mil por ano."},{"id":3371,"materia":"trib","nivel":2,"enunciado":"No lucro presumido, o percentual de presunção do IRPJ para a atividade comercial em geral é de:","opcoes":["8%","32%","16%","1,6%"],"explicacao":"Para prestação de serviços em geral, 32%."},{"id":3372,"materia":"trib","nivel":2,"enunciado":"O lucro arbitrado é aplicado, por exemplo, quando:","opcoes":["A escrituração do contribuinte é imprestável para apurar o lucro real","A empresa tem lucro muito alto","A empresa é optante do Simples","O contribuinte pede desconto no imposto por dificuldade financeira"],"explicacao":"Pode ser aplicado pelo Fisco ou pelo próprio contribuinte."},{"id":3373,"materia":"trib","nivel":3,"enunciado":"O município que optar por fiscalizar e cobrar o ITR, nos termos da lei, fica com:","opcoes":["100% da arrecadação dos imóveis nele situados","50% da arrecadação","25% da arrecadação","Nenhuma parte da arrecadação, que fica toda com a União"],"explicacao":"Art. 158, II da CF."},{"id":3374,"materia":"trib","nivel":3,"enunciado":"A CIDE-Combustíveis tem sua arrecadação destinada, entre outros fins, a:","opcoes":["Programas de infraestrutura de transportes e projetos ambientais","Pagamento de juros da dívida externa","Custeio do Poder Judiciário","Financiamento de campanhas eleitorais e partidos políticos"],"explicacao":"Art. 177, § 4º, II da CF."},{"id":3375,"materia":"trib","nivel":3,"enunciado":"A CIDE da Lei 10.168/2000 incide sobre valores remetidos ao exterior a título de:","opcoes":["Royalties e remuneração por tecnologia e assistência técnica","Turismo de pessoas físicas","Doações a entidades religiosas e templos de qualquer culto","Importação de alimentos"],"explicacao":"Financia o programa de interação universidade-empresa."},{"id":3376,"materia":"trib","nivel":3,"enunciado":"Na industrialização, segundo o regulamento do IPI, NÃO é modalidade:","opcoes":["Revenda sem alteração","Transformação","Beneficiamento","Acondicionamento para transporte"],"explicacao":"Também são modalidades montagem e renovação ou recondicionamento."},{"id":3377,"materia":"trib","nivel":4,"enunciado":"O IOF incidente sobre o ouro como ativo financeiro tem alíquota mínima de:","opcoes":["1%, com receita repartida entre estado e município de origem","5%, com receita só da União","0,38%, com receita só do estado","10%, com receita destinada só ao município de origem"],"explicacao":"Art. 153, § 5º: 30% ao estado e 70% ao município de origem."},{"id":3378,"materia":"trib","nivel":4,"enunciado":"Pela Lei 14.596/2023, as regras de preço de transferência passaram a seguir o princípio:","opcoes":["Arm's length (preço de livre concorrência entre partes não vinculadas)","Do custo de produção acrescido de margem fixa de lucro definida em lei","Do preço mínimo fixado pela Receita","Da alíquota única de 15%"],"explicacao":"Alinhou o Brasil ao padrão da OCDE."},{"id":3379,"materia":"trib","nivel":4,"enunciado":"No processo administrativo fiscal (Decreto 70.235/1972), o prazo para impugnar o lançamento é de:","opcoes":["30 dias","15 dias","60 dias","10 dias"],"explicacao":"Também é de 30 dias o recurso voluntário ao CARF."},{"id":3380,"materia":"eco","nivel":0,"enunciado":"O problema econômico fundamental decorre da:","opcoes":["Escassez de recursos diante de necessidades ilimitadas","Abundância de recursos naturais e de mão de obra","Falta de dinheiro nos bancos","Existência de impostos"],"explicacao":"Por isso é preciso escolher como usar os recursos."},{"id":3381,"materia":"eco","nivel":0,"enunciado":"Quando o preço de um produto sobe, pela lei da demanda, a quantidade demandada tende a:","opcoes":["Cair","Subir","Ficar igual","Dobrar"],"explicacao":"Relação inversa entre preço e quantidade demandada."},{"id":3382,"materia":"eco","nivel":0,"enunciado":"PIB é a sigla de:","opcoes":["Produto Interno Bruto","Preço Interno Básico","Produção Industrial Brasileira","Poupança Individual Bruta"],"explicacao":"Valor dos bens e serviços finais produzidos no país."},{"id":3383,"materia":"eco","nivel":0,"enunciado":"No Brasil, a taxa básica de juros da economia é a:","opcoes":["Selic","IPCA","TR","Ibovespa"],"explicacao":"Definida pelo Copom do Banco Central."},{"id":3384,"materia":"eco","nivel":1,"enunciado":"O custo de oportunidade de uma escolha é:","opcoes":["O valor da melhor alternativa abandonada","O preço pago em dinheiro pela opção escolhida","O imposto incidente","O lucro obtido"],"explicacao":"Toda escolha implica renunciar a algo."},{"id":3385,"materia":"eco","nivel":1,"enunciado":"Bens complementares são aqueles em que:","opcoes":["O aumento do preço de um reduz a demanda do outro","O aumento do preço de um aumenta a demanda do outro","Um substitui o outro no consumo","Não há qualquer relação de consumo"],"explicacao":"Ex.: carro e combustível."},{"id":3386,"materia":"eco","nivel":1,"enunciado":"Um bem inferior é aquele cuja demanda:","opcoes":["Cai quando a renda do consumidor aumenta","Sobe sempre que a renda do consumidor aumenta","Não depende da renda","Só existe em países pobres"],"explicacao":"Ex.: produtos de segunda linha trocados por melhores com mais renda."},{"id":3387,"materia":"eco","nivel":1,"enunciado":"Pela ótica da despesa, o PIB é igual a:","opcoes":["C + I + G + (X − M)","C + S + T","Salários + lucros − impostos","Exportações − importações"],"explicacao":"Consumo, investimento, gastos do governo e exportações líquidas."},{"id":3388,"materia":"eco","nivel":1,"enunciado":"O índice oficial usado no sistema de metas de inflação do Brasil é o:","opcoes":["IPCA","IGP-M","INPC","IPC-Fipe"],"explicacao":"Calculado pelo IBGE."},{"id":3389,"materia":"eco","nivel":2,"enunciado":"Quando a demanda é preço-elástica (elasticidade maior que 1), um aumento de preço provoca:","opcoes":["Queda da receita total","Aumento da receita total","Receita total constante","Aumento da quantidade demandada"],"explicacao":"A quantidade cai proporcionalmente mais que o preço sobe."},{"id":3390,"materia":"eco","nivel":2,"enunciado":"Em concorrência perfeita, a empresa maximiza lucro produzindo onde:","opcoes":["Preço é igual ao custo marginal","Preço é o dobro do custo médio total","Receita total é máxima","Custo fixo é zero"],"explicacao":"As empresas são tomadoras de preço."},{"id":3391,"materia":"eco","nivel":2,"enunciado":"O monopolista maximiza o lucro produzindo onde:","opcoes":["Receita marginal é igual ao custo marginal","Preço é igual ao custo marginal","Preço é igual ao custo médio","Demanda é perfeitamente elástica ao preço"],"explicacao":"Por isso o preço fica acima do custo marginal."},{"id":3392,"materia":"eco","nivel":2,"enunciado":"Bens públicos puros se caracterizam por serem:","opcoes":["Não rivais e não excludentes","Rivais e excludentes","Vendidos apenas pelo governo","Sempre gratuitos e escassos"],"explicacao":"Ex.: defesa nacional e iluminação pública."},{"id":3393,"materia":"eco","nivel":2,"enunciado":"A poluição causada por uma fábrica que prejudica moradores vizinhos é exemplo de:","opcoes":["Externalidade negativa","Bem público","Monopólio natural","Assimetria de preços no varejo"],"explicacao":"Pode ser corrigida por um imposto pigouviano."},{"id":3394,"materia":"eco","nivel":2,"enunciado":"No dilema do prisioneiro, o equilíbrio de Nash leva os jogadores a:","opcoes":["Um resultado pior para ambos do que se cooperassem","O melhor resultado possível para os dois, por meio de cooperação","A cooperação automática","Ganhos iguais à soma máxima"],"explicacao":"A estratégia dominante de cada um é não cooperar."},{"id":3395,"materia":"eco","nivel":2,"enunciado":"Segundo Musgrave, a função do Estado de fornecer bens públicos é a função:","opcoes":["Alocativa","Distributiva","Estabilizadora","Reguladora"],"explicacao":"Distributiva: ajustar a renda; estabilizadora: emprego e preços."},{"id":3396,"materia":"eco","nivel":3,"enunciado":"A seleção adversa ocorre:","opcoes":["Antes do contrato, por informação oculta de uma das partes","Depois do contrato, por mudança de comportamento de uma das partes","Apenas em mercados de concorrência perfeita","Somente quando há impostos"],"explicacao":"Risco moral é a ação oculta depois do contrato."},{"id":3397,"materia":"eco","nivel":3,"enunciado":"O ônus de um tributo recai mais sobre o lado do mercado que tiver:","opcoes":["Demanda ou oferta mais inelástica","Maior número de empresas concorrentes","Maior renda média","Menor custo fixo"],"explicacao":"Quem tem menos opção de reagir ao preço suporta mais."},{"id":3398,"materia":"eco","nivel":3,"enunciado":"O índice de Laspeyres usa como pesos:","opcoes":["As quantidades do período-base","As quantidades do período atual","A média das quantidades","Os preços futuros"],"explicacao":"O de Paasche usa quantidades do período atual."},{"id":3399,"materia":"eco","nivel":3,"enunciado":"No modelo IS-LM, uma política fiscal expansionista desloca:","opcoes":["A curva IS para a direita","A curva LM para a direita","A curva IS para a esquerda","A curva LM para a esquerda"],"explicacao":"Eleva renda e juros, no caso geral."},{"id":3400,"materia":"eco","nivel":4,"enunciado":"Na economia comportamental, a aversão à perda significa que as pessoas:","opcoes":["Sentem mais uma perda do que um ganho de mesmo valor","Preferem sempre o risco","São indiferentes a ganhos e perdas de mesmo valor","Decidem sempre de forma racional"],"explicacao":"Conceito de Kahneman e Tversky."},{"id":3401,"materia":"eco","nivel":4,"enunciado":"O peso morto de um tributo representa:","opcoes":["A perda de eficiência por transações que deixam de ocorrer","O total arrecadado pelo governo","O custo de cobrar o imposto","O tributo não pago pelos sonegadores durante o exercício"],"explicacao":"Perda de excedente não compensada pela arrecadação."},{"id":3402,"materia":"eco","nivel":4,"enunciado":"Na transição para o Plano Real, a unidade de conta usada antes da nova moeda foi a:","opcoes":["URV","UFIR","ORTN","BTN"],"explicacao":"Unidade Real de Valor, de 1994."},{"id":3403,"materia":"aud","nivel":0,"enunciado":"Na auditoria, circularização é o procedimento de:","opcoes":["Pedir confirmação de saldos diretamente a terceiros","Fazer circular os papéis de trabalho entre os auditores da equipe","Contar o dinheiro em caixa","Recalcular os impostos"],"explicacao":"Chamada também de confirmação externa."},{"id":3404,"materia":"aud","nivel":0,"enunciado":"O auditor independente emite, ao final do trabalho, um:","opcoes":["Relatório com sua opinião sobre as demonstrações","Balanço patrimonial da empresa","Contrato de prestação de serviço para o próximo ano","Auto de infração"],"explicacao":"Opinião sobre as demonstrações contábeis."},{"id":3405,"materia":"aud","nivel":1,"enunciado":"Pela NBC TA 200, o auditor busca obter segurança:","opcoes":["Razoável de que as demonstrações estão livres de distorção relevante","Absoluta de que não há nenhum erro ou fraude nas demonstrações","Mínima, apenas sobre o caixa","Total sobre todas as fraudes"],"explicacao":"Segurança razoável é alto nível, mas não absoluto."},{"id":3406,"materia":"aud","nivel":1,"enunciado":"A opinião adversa é emitida quando as distorções são:","opcoes":["Relevantes e generalizadas","Relevantes, mas não generalizadas","Irrelevantes","Inexistentes"],"explicacao":"Se relevantes mas não generalizadas, cabe ressalva."},{"id":3407,"materia":"aud","nivel":1,"enunciado":"A abstenção de opinião ocorre quando o auditor:","opcoes":["Não obtém evidência suficiente e os possíveis efeitos são relevantes e generalizados","Encontra uma distorção pequena","Discorda do valor dos honorários","Termina o trabalho antes do prazo combinado com a administração da empresa"],"explicacao":"NBC TA 705."},{"id":3408,"materia":"aud","nivel":1,"enunciado":"Os testes que verificam se os controles internos funcionam são os testes de:","opcoes":["Observância (controle)","Superavaliação","Substantivos","Recálculo de tributos devidos"],"explicacao":"Os substantivos buscam distorções nos saldos."},{"id":3409,"materia":"aud","nivel":2,"enunciado":"Dos componentes do risco de auditoria, o auditor controla diretamente o risco:","opcoes":["De detecção","Inerente","De controle","De mercado"],"explicacao":"Os riscos inerente e de controle são da entidade."},{"id":3410,"materia":"aud","nivel":2,"enunciado":"Para testar superavaliação de um ativo, o auditor parte:","opcoes":["Do registro contábil para o documento de suporte","Do documento para o registro","Do relatório anterior","Da declaração do cliente sobre o saldo"],"explicacao":"Testa existência. Na subavaliação, do documento para o registro."},{"id":3411,"materia":"aud","nivel":2,"enunciado":"Quanto à confiabilidade, a evidência obtida de fonte externa independente é, em regra:","opcoes":["Mais confiável que a gerada internamente","Menos confiável que a explicação verbal do gestor","Igual a qualquer outra","Desconsiderada pelas normas"],"explicacao":"NBC TA 500."},{"id":3412,"materia":"aud","nivel":2,"enunciado":"Saldo credor na conta caixa indica, em regra, que a empresa:","opcoes":["Pagou despesas com recursos não contabilizados, sugerindo omissão de receita","Teve lucro elevado no período","Fez aplicação financeira","Recebeu empréstimo bancário de longo prazo, ainda não registrado no balanço"],"explicacao":"Caixa não pode ter saldo negativo."},{"id":3413,"materia":"aud","nivel":2,"enunciado":"A manutenção no balanço de obrigações já pagas caracteriza:","opcoes":["Passivo fictício, que permite presumir omissão de receitas","Reserva de lucros","Provisão obrigatória","Ajuste de avaliação patrimonial de ativos financeiros"],"explicacao":"Presunção prevista na legislação do IR."},{"id":3414,"materia":"aud","nivel":3,"enunciado":"Pela legislação do IR, depósitos bancários de origem não comprovada pelo titular caracterizam:","opcoes":["Omissão de receita ou de rendimento","Doação isenta","Empréstimo presumido","Ganho de capital tributado à parte"],"explicacao":"Art. 42 da Lei 9.430/1996."},{"id":3415,"materia":"aud","nivel":3,"enunciado":"Pela LC 105/2001, as autoridades fiscais podem examinar dados bancários do contribuinte quando:","opcoes":["Houver processo ou procedimento fiscal em curso e o exame for indispensável","Quiserem, sem nenhum procedimento","Houver ordem judicial em todo e qualquer caso, sem exceção","O banco autorizar"],"explicacao":"Art. 6º, validado pelo STF em 2016."},{"id":3416,"materia":"aud","nivel":3,"enunciado":"No ICMS, o crédito do ativo permanente controlado no CIAP é apropriado em:","opcoes":["48 parcelas mensais","12 parcelas mensais","Parcela única","60 parcelas mensais"],"explicacao":"Art. 20, § 5º da LC 87/1996."},{"id":3417,"materia":"aud","nivel":3,"enunciado":"Na NBC TA 530, risco de amostragem é o risco de:","opcoes":["A conclusão baseada na amostra ser diferente da que seria obtida examinando toda a população","O auditor perder os papéis de trabalho","O cliente recusar a amostra","A amostra ter custo maior que o previsto no planejamento, exigindo novos honorários do cliente"],"explicacao":"Pode levar a conclusões erradas sobre controles ou saldos."},{"id":3418,"materia":"aud","nivel":4,"enunciado":"A chave de acesso da NF-e é composta por:","opcoes":["44 dígitos","20 dígitos","32 dígitos","12 dígitos"],"explicacao":"Identifica a nota de forma única."},{"id":3419,"materia":"aud","nivel":4,"enunciado":"A documentação de auditoria (papéis de trabalho) pertence:","opcoes":["Ao auditor","Ao cliente auditado","Ao Conselho Federal de Contabilidade","À Receita Federal"],"explicacao":"NBC TA 230."},{"id":3420,"materia":"dados","nivel":0,"enunciado":"Big Data se refere a conjuntos de dados:","opcoes":["Muito grandes, variados e gerados em alta velocidade","Pequenos e organizados em uma única planilha eletrônica","Guardados apenas em papel","Sem nenhuma utilidade prática"],"explicacao":"Exigem ferramentas especiais de armazenamento e análise."},{"id":3421,"materia":"dados","nivel":0,"enunciado":"Python e R são exemplos de:","opcoes":["Linguagens de programação usadas em ciência de dados","Sistemas operacionais","Navegadores de internet e redes sociais","Antivírus"],"explicacao":"Muito usadas em análise estatística e aprendizado de máquina."},{"id":3422,"materia":"dados","nivel":1,"enunciado":"Os 'Vs' clássicos do Big Data incluem:","opcoes":["Volume, velocidade e variedade","Valor, voto e vigência","Visão, vetor e voltagem","Vírus, vulnerabilidade e verificação"],"explicacao":"Muitos autores somam veracidade e valor."},{"id":3423,"materia":"dados","nivel":1,"enunciado":"Um banco de dados NoSQL se diferencia do relacional por:","opcoes":["Não depender obrigatoriamente de tabelas com esquema fixo","Não armazenar nenhum dado","Funcionar apenas sem internet","Usar somente planilhas eletrônicas compartilhadas em rede"],"explicacao":"Modelos: chave-valor, documento, colunar e grafo."},{"id":3424,"materia":"dados","nivel":1,"enunciado":"O MongoDB é um banco NoSQL do tipo:","opcoes":["Orientado a documentos","Grafo","Relacional","Chave-valor puro em memória"],"explicacao":"Armazena documentos em formato semelhante ao JSON."},{"id":3425,"materia":"dados","nivel":2,"enunciado":"O Neo4j é um banco NoSQL orientado a:","opcoes":["Grafos","Documentos","Colunas","Planilhas"],"explicacao":"Ideal para relações, como redes de empresas e sócios."},{"id":3426,"materia":"dados","nivel":2,"enunciado":"Data lake se diferencia de data warehouse por armazenar:","opcoes":["Dados brutos em vários formatos, inclusive não estruturados","Apenas dados já tratados, integrados e estruturados para relatórios","Somente imagens","Apenas cópias de segurança"],"explicacao":"O data warehouse guarda dados integrados e estruturados para análise."},{"id":3427,"materia":"dados","nivel":2,"enunciado":"A sigla ETL, em integração de dados, significa:","opcoes":["Extrair, transformar e carregar","Editar, testar e lançar","Exportar, transmitir e ler arquivos","Estimar, tabular e listar"],"explicacao":"Do inglês extract, transform, load."},{"id":3428,"materia":"dados","nivel":2,"enunciado":"O algoritmo k-means é usado para:","opcoes":["Agrupar dados semelhantes (clusterização)","Classificar dados já rotulados por especialistas","Criptografar arquivos","Compactar imagens"],"explicacao":"É técnica de aprendizado não supervisionado."},{"id":3429,"materia":"dados","nivel":2,"enunciado":"A regressão logística é indicada para prever:","opcoes":["Uma variável categórica, como sim ou não","Um valor contínuo, como a renda mensal","A ordem alfabética de nomes","O tamanho de um arquivo"],"explicacao":"Estima a probabilidade de um evento."},{"id":3430,"materia":"dados","nivel":3,"enunciado":"Overfitting ocorre quando o modelo:","opcoes":["Se ajusta demais aos dados de treino e generaliza mal","Não aprende nem os dados de treino, ficando simples demais","Usa poucos dados de teste","Roda mais rápido que o esperado"],"explicacao":"Underfitting é o oposto."},{"id":3431,"materia":"dados",